import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

// NodeNext resolution does not expose instancePath on AJV's re-exported types; use a local shape.
interface AjvError {
  instancePath?: string;
  keyword?: string;
  message?: string;
}

const ajv = new Ajv({strictSchema: false, strictTypes: false, validateFormats: false});

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  compiledValidator?: ValidateFunction;
}

function formatValidationErrors(errors: AjvError[]): string {
  return errors.map(e => `${e.instancePath ? e.instancePath + ' ' : ''}${e.message ?? 'invalid'}`.trim()).join('; ');
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let compiledValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        compiledValidator = ajv.compile(resolved.inputSchema as object);
      } catch (err) {
        throw new Error(`Tool "${resolved.name}": invalid inputSchema — ${(err as Error).message}`, {cause: err});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, compiledValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private resolveValidator(source: ToolDefinitionSource): ValidateFunction {
    const resolved = this.resolveDefinition(source);
    const schema = resolved.inputSchema as object;
    const cached = this.schemaCache.get(schema);
    if (cached) return cached;
    const compiled = ajv.compile(schema);
    this.schemaCache.set(schema, compiled);
    return compiled;
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for the full contract. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const validate = tool.compiledValidator ?? this.resolveValidator(tool.definitionSource);

    if (!validate(input)) {
      const errors = (validate.errors ?? []) as AjvError[];
      const result = formatValidationErrors(errors);
      log.warn('tool', 'input validation failed', {
        name,
        errors: errors.map(e => ({path: e.instancePath, keyword: e.keyword, message: e.message})),
      });
      return {result};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

const BASE_SCHEMA: ToolDefinition['inputSchema'] = {type: 'object', properties: {name: {type: 'string'}}};
const REQUIRED_SCHEMA: ToolDefinition['inputSchema'] = {
  type: 'object',
  properties: {name: {type: 'string'}},
  required: ['name'],
};

describe('ToolRegistry', () => {
  describe('execute — valid input', () => {
    it('passes valid input with extra properties through to executor unchanged', async () => {
      const registry = new ToolRegistry();
      let received: Record<string, unknown> = {};
      registry.register({name: 'greet', description: 'greet', inputSchema: BASE_SCHEMA}, async input => {
        received = input;
        return 'hi';
      });

      await registry.execute('greet', {name: 'Alice', extra: 'ignored'});

      expect(received).toEqual({name: 'Alice', extra: 'ignored'});
    });
  });

  describe('execute — unknown tool', () => {
    it('throws for an unregistered tool name', async () => {
      const registry = new ToolRegistry();

      await expect(registry.execute('no_such_tool', {})).rejects.toThrow('Unknown tool: no_such_tool');
    });
  });

  describe('execute — static schema compiled at register time', () => {
    it('applies the schema compiled at register time even when the definition object is mutated afterwards', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;
      const definition: ToolDefinition = {
        name: 'static_tool',
        description: 'test',
        inputSchema: {...REQUIRED_SCHEMA},
      };
      registry.register(definition, async () => {
        executorCalls += 1;
        return 'done';
      });

      // Mutate the stored schema reference after registration.
      definition.inputSchema = {type: 'object'};

      // Using compiled validator (not re-reading definition) means mutation is ignored and 'name' is still required.
      const result = await registry.execute('static_tool', {});

      expect({executorCalls, rejected: /required/i.test(result.result)}).toEqual({
        executorCalls: 0,
        rejected: true,
      });
    });
  });

  describe('execute — function-valued definition source', () => {
    it('validates against the schema the source returns for that call, not a stale one', async () => {
      const registry = new ToolRegistry();
      const schemas: ToolDefinition['inputSchema'][] = [
        {type: 'object', properties: {a: {type: 'string'}}, required: ['a']},
        {type: 'object', properties: {b: {type: 'string'}}, required: ['b']},
      ];
      let schemaIndex = 0;
      registry.register(
        () => ({name: 'switcher', description: 'changes schema', inputSchema: schemas[schemaIndex]!}),
        async () => 'ok'
      );

      schemaIndex = 0;
      const result1 = await registry.execute('switcher', {b: 'x'});

      schemaIndex = 1;
      const result2 = await registry.execute('switcher', {b: 'x'});

      expect({
        firstRejected: /required/i.test(result1.result) && result1.result.includes('a'),
        secondPassed: result2.result === 'ok',
      }).toEqual({firstRejected: true, secondPassed: true});
    });
  });

  describe('execute — static compiled exactly once', () => {
    it('compiles the schema once at register time and reuses it across ten execute calls', async () => {
      const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
      try {
        const registry = new ToolRegistry();
        const before = compileSpy.mock.calls.length;
        registry.register({name: 'once', description: 'test', inputSchema: REQUIRED_SCHEMA}, async () => 'ok');
        const afterRegister = compileSpy.mock.calls.length;
        for (let i = 0; i < 10; i++) {
          await registry.execute('once', {name: 'x'});
        }
        expect({
          compiledAtRegister: afterRegister - before,
          recompiledDuringExecute: compileSpy.mock.calls.length - afterRegister,
        }).toEqual({compiledAtRegister: 1, recompiledDuringExecute: 0});
      } finally {
        compileSpy.mockRestore();
      }
    });
  });
});

